import { Field } from '@base-ui/react/field';
import { mergeProps } from '@base-ui/react/merge-props';
import { useState, type ComponentProps, type CSSProperties, type Ref } from 'react';
import { useRender } from '@base-ui/react/use-render';
import { ClearControlButton, resetNativeValue, type ClearableProps } from '../../utils/clear-control';
import { useFieldVariant } from '../../field-variant/field-variant-context';
import { useAutosizeFallback } from './useAutosizeFallback';
import { cn } from '../../utils/cn';
import { CharCount, useCharCount, type CharCountProps } from '../../utils/char-count';
import { textareaAutosizeBounds, textareaVariants, type TextareaVariantProps } from './textarea.variants';

type NativeTextareaProps = Omit<
  ComponentProps<'textarea'>,
  'className' | 'ref' | 'value' | 'defaultValue' | 'onChange'
>;

export interface TextareaProps extends NativeTextareaProps, TextareaVariantProps, ClearableProps, CharCountProps {
  /** Minimum content rows with autosize; otherwise ignored. Positive finite values only. */
  minRows?: number;
  /** Maximum content rows with autosize; overflow scrolls. Positive finite values only. */
  maxRows?: number;
  className?: string;
  ref?: Ref<HTMLTextAreaElement>;
  value?: string;
  defaultValue?: string;
  onChange?: ComponentProps<'textarea'>['onChange'];
  /** Called with the new string value (mirrors Input's `onValueChange`). */
  onValueChange?: (value: string) => void;
  /** Marks the value as invalid (sets aria-invalid). Inside a Field, `Field invalid` does this. */
  invalid?: boolean;
}

/**
 * Multi-line text input. Renders a native <textarea> through Base UI Field.Control, so a
 * surrounding Field links its label, description and error and tracks dirty/touched state.
 * `autosize` grows the box with its content via native `field-sizing: content`, with a measured fallback.
 */
export function Textarea({
  size = 'auto',
  variant,
  resize,
  autosize,
  minRows,
  maxRows,
  style,
  invalid,
  className,
  ref,
  id,
  name,
  disabled,
  value,
  defaultValue,
  onValueChange,
  rows = 4,
  clearable,
  clearLabel,
  onClear,
  showCount,
  maxCount,
  countStrategy,
  ...rest
}: TextareaProps) {
  const maximum = autosize && maxRows !== undefined && Number.isFinite(maxRows) && maxRows > 0 ? maxRows : undefined;
  const minimum =
    autosize && minRows !== undefined && Number.isFinite(minRows) && minRows > 0
      ? Math.min(minRows, maximum ?? Infinity)
      : undefined;
  const boundedStyle = {
    ...style,
    ...(minimum !== undefined && { '--textarea-min-rows': minimum }),
    ...(maximum !== undefined && { '--textarea-max-rows': maximum }),
  } as CSSProperties;
  const fieldVariant = useFieldVariant(variant);
  const [control, setControl] = useState<HTMLTextAreaElement | null>(null);
  const [inner, setInner] = useState(defaultValue ?? '');
  const counter = useCharCount(value ?? inner, { showCount, maxCount, countStrategy }, rest.maxLength);
  useAutosizeFallback(control, autosize, value ?? inner, minimum, maximum, size);
  const hasValue = (value ?? (control ? control.value : inner)).length > 0;
  const textarea = useRender({
    ref: [ref ?? null, setControl],
    render: (
      <Field.Control
        id={id}
        name={name}
        disabled={disabled}
        value={value}
        defaultValue={defaultValue}
        onValueChange={(v) => {
          setInner(v);
          onValueChange?.(v);
        }}
        render={(controlProps) => (
          <textarea
            {...mergeProps<'textarea'>(controlProps as ComponentProps<'textarea'>, rest, {
              rows: autosize ? undefined : rows,
              style: minimum !== undefined || maximum !== undefined ? boundedStyle : style,
              'aria-invalid': invalid || undefined,
              ...(showCount && {
                'aria-describedby': [controlProps['aria-describedby'], rest['aria-describedby'], counter.descriptionId]
                  .filter(Boolean)
                  .join(' '),
                'data-over-limit': counter.over ? '' : undefined,
              }),
              className: cn(
                textareaVariants({ variant: fieldVariant, size, resize, autosize }),
                minimum !== undefined && textareaAutosizeBounds.min,
                maximum !== undefined && textareaAutosizeBounds.max,
                clearable && 'pe-9',
                className,
              ),
            })}
          />
        )}
      />
    ),
  });
  const field = !clearable ? (
    textarea
  ) : (
    <div className="relative">
      {textarea}
      {hasValue && !disabled && !rest.readOnly && (
        <ClearControlButton
          className="absolute top-2 end-2 min-h-6 min-w-6"
          control={control}
          clearLabel={clearLabel}
          onClick={() => {
            if (!control) return;
            resetNativeValue(control);
            onClear?.();
            control.focus();
          }}
        />
      )}
    </div>
  );
  if (!showCount) return field;
  return (
    <div className="flex flex-col gap-1">
      {field}
      <div className="flex justify-end">
        <CharCount {...counter} />
      </div>
    </div>
  );
}

export { Textarea, type TextareaProps } from './Textarea';
export { textareaVariants, type TextareaVariantProps } from './textarea.variants';
export { doc as textareaDoc } from './Textarea.doc';

import { fieldControlVariants } from '../../field-variant/field-control-variants';
import { tv, type VariantProps } from '../../utils/tv';

export const textareaVariants = tv({
  base: [
    'block w-full min-w-0 rounded-md border border-border bg-background px-3 py-2 text-foreground shadow-sm',
    'placeholder:text-muted-foreground transition-colors motion-reduce:transition-none',
    'focus-visible:border-primary/60 focus-ring',
    'data-invalid:border-destructive/70 aria-invalid:border-destructive/70',
    'disabled:cursor-disabled disabled:bg-secondary/50 disabled:text-muted-foreground',
    'read-only:bg-secondary/40',
  ],
  variants: {
    variant: fieldControlVariants,

    size: {
      lg: 'px-4 text-[14.5px] leading-6 rounded-lg',
      auto: 'px-field text-[13px] leading-6',
      sm: 'text-[12px] leading-5',
      md: 'text-[13px] leading-6',
    },
    resize: {
      none: 'resize-none',
      vertical: 'resize-y',
    },
    autosize: {
      true: 'field-sizing-content min-h-[88px] resize-none',
      false: '',
    },
  },
  defaultVariants: { variant: 'outline', size: 'auto', resize: 'none', autosize: false },
});

export type TextareaVariantProps = VariantProps<typeof textareaVariants>;

/** Applied only when the corresponding autosize row bound is valid. */
export const textareaAutosizeBounds = {
  min: 'min-h-[calc(var(--textarea-min-rows)*1lh+1rem+2px)]',
  max: 'max-h-[calc(var(--textarea-max-rows)*1lh+1rem+2px)] overflow-y-auto',
};

import { useLayoutEffect } from 'react';

function resizeTextarea(
  control: HTMLTextAreaElement,
  minRows: number | undefined,
  maxRows: number | undefined,
  size: string | undefined,
) {
  const originalHeight = control.style.height;
  const originalOverflow = control.style.overflowY;
  const computed = getComputedStyle(control);
  const pixels = (value: string) => Number.parseFloat(value) || 0;
  const lineHeight = pixels(computed.lineHeight) || (size === 'sm' ? 20 : 24);
  const padding = pixels(computed.paddingTop) + pixels(computed.paddingBottom);
  const border = pixels(computed.borderTopWidth) + pixels(computed.borderBottomWidth);
  const minimum = pixels(computed.minHeight) || (minRows === undefined ? 88 : minRows * lineHeight + padding + border);
  const maximum =
    pixels(computed.maxHeight) || (maxRows === undefined ? Infinity : maxRows * lineHeight + padding + border);
  const caretAtEnd = control.selectionStart === control.value.length && control.selectionEnd === control.value.length;

  // Reset before measuring so deleting content can shrink a previously tall field.
  control.style.height = '0px';
  control.style.overflowY = 'hidden';
  const contentHeight = control.scrollHeight + border;
  const height = Math.max(minimum, Math.min(contentHeight, maximum));
  const measuredHeight = `${height}px`;
  control.style.height = measuredHeight;
  const overflow = contentHeight > height ? 'auto' : 'hidden';
  control.style.overflowY = overflow;
  if (caretAtEnd) control.scrollTop = control.scrollHeight;

  return () => {
    if (control.style.height === measuredHeight) control.style.height = originalHeight;
    if (control.style.overflowY === overflow) control.style.overflowY = originalOverflow;
  };
}

/** Native field-sizing needs no script to size; it only needs the capped field kept at its end. */
function scrollToEnd(control: HTMLTextAreaElement) {
  const caretAtEnd = control.selectionStart === control.value.length && control.selectionEnd === control.value.length;
  if (caretAtEnd && control.scrollHeight > control.clientHeight) control.scrollTop = control.scrollHeight;
}

/** Native field-sizing needs no script; measure only after a client commit. */
export function useAutosizeFallback(
  control: HTMLTextAreaElement | null,
  autosize: boolean | undefined,
  value: string,
  minRows: number | undefined,
  maxRows: number | undefined,
  size: string | undefined,
) {
  useLayoutEffect(() => {
    if (!autosize || !control) return;
    // The browser keeps only the caret line visible, leaving the bottom padding out of view.
    if (globalThis.CSS?.supports?.('field-sizing', 'content')) {
      scrollToEnd(control);
      return;
    }

    return resizeTextarea(control, minRows, maxRows, size);
  }, [control, autosize, value, minRows, maxRows, size]);
}

/** Only alternate chrome overrides the existing outline classes. Forced colours retain a boundary. */
export const fieldControlVariants = {
  outline: '',
  filled: 'border-transparent bg-secondary shadow-none forced-colors:border-[ButtonText]',
  ghost: 'border-transparent bg-transparent shadow-none hover:bg-secondary/50 forced-colors:border-[ButtonText]',
} as const;

/** Picker hover must not mask a keyboard-focus, open-popup or error border. */
export const fieldPickerHover =
  'hover:border-transparent hover:focus-visible:border-primary/60 hover:data-popup-open:border-primary/60 hover:data-invalid:border-destructive/70 hover:aria-invalid:border-destructive/70';

import { createContext, useContext } from 'react';

/** Field chrome; outline preserves the original bordered appearance. */
export type FieldControlVariant = 'outline' | 'filled' | 'ghost';
export const FieldVariantContext = createContext<FieldControlVariant>('outline');

/** Explicit props win over the nearest provider, then the outline default. */
export function useFieldVariant(variant?: FieldControlVariant): FieldControlVariant {
  const inherited = useContext(FieldVariantContext);
  return variant ?? inherited;
}

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** JSX skeleton showing the public compound parts. */
  anatomy?: string;
  /** State attribute, styled part and product-agnostic meaning. */
  dataAttributes?: Array<[attribute: string, part: string, meaning: string]>;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}

/**
 * Hook documentation contract. Every hook in `src/hooks/index.ts` has a `hooks/<useName>.doc.ts`
 * exporting `doc: HookDoc`; the registry build, the docs Hooks page and the coverage test read it.
 */
export interface HookDoc {
  /** Public hook name, e.g. "useClipboard". */
  name: string;
  /** Lifecycle badge. */
  status: ComponentDoc['status'];
  description: string;
  /** Call signature, e.g. "useClipboard(options?): { copy, status, copied, error, reset }". */
  signature: string;
  /**
   * What the hook returns without a DOM (server render and first hydration render). Put literal
   * values in backticks: the SSR test checks that the example's server output contains each one.
   */
  server: string;
  /** Non-hook helpers exported next to the hook that this doc covers, e.g. "readLocalStorageValue". Every `use*` hook has its own doc. */
  also?: string[];
}
